mapper.select:
/** * selectWorkHrPreconList : isry.couns.mngr.workaltmntmng.mapper.WorkHrPreconMapper : 그리드 상담자 목록 조회 */ SELECT DISTINCT BB.USER_ID AS CNSLTNT_ID /** 상담자 아이디 **/ , C##RG.DEC_B64(CC.FLNM_ENCPT) AS CNSLTNT_NM /** 상담자 이름 **/ FROM AYC110 AA /** 근무배정표 월별 **/ , SAA200 BB /** 기관 사용자 **/ , SCA100 CC /** 종사자 **/ , AYC100 EE /** 근무배정표 일별 **/ WHERE 1=1 AND AA.BIZ_PLAN_MNG_NO = EE.BIZ_PLAN_MNG_NO AND BB.USER_ID = EE.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND CC.OGDP_DEPT_CD = #{instNo} /* 소속부서코드 */
AND AA.CRTR_YM LIKE #{crtrYm} || '%'
